52-  bool Write(const void *data, size_t length) {
53-    if (!length) return false;
54-
55-    const size_t orig_length = length;
56-    size_t offset = 0;
57-
58-    size_t chksum_offset = Tell() & 3;
59-    if (chksum_offset) {
60-      const size_t l = std::min(length, static_cast<size_t>(4) - chksum_offset);
61-      uint32_t tmp = 0;
62-      std::memcpy(reinterpret_cast<uint8_t *>(&tmp) + chksum_offset, data, l);
63-      chksum_ += ntohl(tmp);
64-      length -= l;
65-      offset += l;
66-    }
67-
68-    while (length >= 4) {
69-      uint32_t tmp;
70-      std::memcpy(&tmp, reinterpret_cast<const uint8_t *>(data) + offset,
71-        sizeof(uint32_t));
72-      chksum_ += ntohl(tmp);
73-      length -= 4;
74-      offset += 4;
75-    }
76-
77-    if (length) {
78-      if (length > 4) return false;  // not reached
79-      uint32_t tmp = 0;
80-      std::memcpy(&tmp,
81-                  reinterpret_cast<const uint8_t*>(data) + offset, length);
82-      chksum_ += ntohl(tmp);
83-    }
84-
85-    return WriteRaw(data, orig_length);
86-  }
